SELECT qrySPCDurchschnittUN1CE1a.Elektrolyseur, Count(qrySPCDurchschnittUN1CE1a.i) AS CountOfi, Max(qrySPCDurchschnittUN1CE1a.i) AS MaxOfi, Min(qrySPCDurchschnittUN1CE1a.i) AS MinOfi, StDev(qrySPCDurchschnittUN1CE1a.i) AS StDevOfi, Avg(qrySPCDurchschnittUN1CE1a.i) AS AvgOfi, Avg(qrySPCDurchschnittUN1CE1a.Energieverbrauch) AS AvgOfEnergieverbrauch, StDev(qrySPCDurchschnittUN1CE1a.Energieverbrauch) AS StDevOfEnergieverbrauch, Min(qrySPCDurchschnittUN1CE1a.Energieverbrauch) AS MinOfEnergieverbrauch, Max(qrySPCDurchschnittUN1CE1a.Energieverbrauch) AS MaxOfEnergieverbrauch, StDev(qrySPCDurchschnittUN1CE1a.Un) AS StDevOfUn, Avg(qrySPCDurchschnittUN1CE1a.Un) AS AvgOfUn, Min(qrySPCDurchschnittUN1CE1a.Un) AS MinOfUn, Max(qrySPCDurchschnittUN1CE1a.Un) AS MaxOfUn, Avg(qrySPCDurchschnittUN1CE1a.CE) AS AvgOfCE, Min(qrySPCDurchschnittUN1CE1a.CE) AS MinOfCE, StDev(qrySPCDurchschnittUN1CE1a.CE) AS StDevOfCE, Max(qrySPCDurchschnittUN1CE1a.CE) AS MaxOfCE, Avg(qrySPCDurchschnittUN1CE1a.iRefSPC) AS AvgOfiRefSPC
FROM qrySPCDurchschnittUN1CE1a
GROUP BY qrySPCDurchschnittUN1CE1a.Elektrolyseur;
